ee:message.ee:set-payload:
%dw 2.0
output application/json
---
createOrderByValueRequest: {
    orderValue: {
        apiClientId: payload.channel,
        orderKey: {
            applicationDN: "System/$(p('asap-sapi.environment'))/ApplicationType/ServiceActivation/Application/1-0;7-2;ASAP/Comp/",
            'type': "javax.oss.order.CreateOrderValue",
            primaryKey: "MS-" ++ payload.identifier
        },
        requestedCompletionDate: payload.provisioningDate,
        services: {
            item: {
                serviceKey: {
                    applicationContext: {
                        factoryClass: "",
                        url: "",
                        systemProperties: ""
                    },
                    applicationDN: "System/$(p('asap-sapi.environment'))/ApplicationType/ServiceActivation/Application/1-0;7-2;ASAP/Comp/",
                    'type': payload.serviceCommand,
                    primaryKey: payload.serviceCommand
                },
                asdlRoute: "ROUTE_TO_NEP",
                serviceValues: {
                    serviceValue : payload.services[0].item.serviceValues map (item, value) -> {
                    name: item.name,
                    value: item.value,
                    'type': "OPTIONAL_SCALAR"
                }
                },

            }
        },
        origin: payload.channel,
        rollbackState: "rollback_required",
        processType: "IMMEDIATE",
        srqAction: "ADD",
        command: payload.action
    }
}
